#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const ll MOD = 1000000007;

class ModInt {
 public:
  ll val;
  ModInt(ll v = 0) : val(v % MOD) {
    if (val < 0) val += MOD;
    if (val >= MOD) { cerr << "ModInt error\n"; exit(1); }
  }
  ModInt operator+(const ModInt& o) const { return ModInt((val + o.val) % MOD); }
  ModInt operator-(const ModInt& o) const { return ModInt((val - o.v + MOD) % MOD); }
  ModInt operator*(const ModInt& o) const { return ModInt((val * o.val) % MOD); }
  ModInt operator/(const ModInt& o) const { return (*this) * o.inv(); }
  ModInt& operator+=(const ModInt& o) { val = (val + o.val) % MOD; return *this; }
  ModInt& operator-=(const ModInt& o) { val = (val - o.val + MOD) % MOD; return *this; }
  ModInt& operator*=(const ModInt& o) { val = (val * o.val) % MOD; return *this; }
  ModInt& operator/=(const ModInt& o) { return (*this) *= o.inv(); }
  ModInt inv() const {
    ll e = MOD - 2, b = val, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return ModInt(r);
  }
};

template<typename T>
vector<vector<T>> multiply(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int n = A.size(), m = A[0].size(), p = B[0].size();
  if (B.size() != m) { cerr << "multiply dim mismatch\n"; exit(1); }
  vector<vector<T>> C(n, vector<T>(p));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < p; ++j)
      for (int k = 0; k < m; ++k)
        C[i][j] = C[i][j] + A[i][k] * B[k][j];
  return C;
}

template<typename T>
vector<T> multiply(const vector<vector<T>>& A, const vector<T>& v) {
  int n = A.size(), m = A[0].size();
  if (v.size() != m) { cerr << "mat-vec dim mismatch\n"; exit(1); }
  vector<T> res(n);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      res[i] = res[i] + A[i][j] * v[j];
  return res;
}

template<typename T>
vector<vector<T>> create2D(int r, int c, const T& def = T()) {
  return vector<vector<T>>(r, vector<T>(c, def));
}

template<typename T>
vector<vector<vector<T>>> create3D(int a, int b, int c, const T& def = T()) {
  return vector<vector<vector<T>>>(a, vector<vector<T>>(b, vector<T>(c, def)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  ll n;
  int d;
  cin >> n >> d;

  auto shift = create3D<ModInt>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d; ++i)
      shift[k][i][(i + k) % d] = ModInt(1);
    shift[k][d][d] = ModInt(1);
  }

  auto unit = create3D<ModInt>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i)
      unit[k][i][i] = ModInt(1);
    for (int i = 0; i < d + 1; ++i)
      unit[k][k][i] = ModInt(1);
  }

  auto identity = create2D<ModInt>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i)
    identity[i][i] = ModInt(1);

  unordered_map<ll, vector<vector<ModInt>>> memo;

  function<vector<vector<ModInt>>(ll)> getMatrix = [&](ll p) -> vector<vector<ModInt>> {
    if (memo.find(p) != memo.end()) return memo[p];
    if (p <= d) {
      auto M = identity;
      for (int k = 0; k < p; ++k)
        M = multiply(unit[k], M);
      return M;
    }
    ll block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = getMatrix(block);
    auto M = child;
    ll rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = multiply(multiply(multiply(shift[d - k], child), shift[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = multiply(multiply(multiply(shift[d - k], getMatrix(rem)), shift[k]), M);
        rem = 0;
      } else break;
    }
    return memo[p] = M;
  };

  auto M = getMatrix(n);
  vector<ModInt> base(d + 1);
  base[d] = ModInt(1);
  auto result = multiply(M, base);
  ModInt total;
  for (auto& x : result) total += x;
  cout << total.val << '\n';
}
